"use client";

import React, { useState } from "react";
import { Compass, AlertTriangle, CheckCircle2, TrendingDown, Target, Award } from "lucide-react";
import { simulateSpendScenario } from "../packages/financial-engine/time-machine";
import { exampleChallenges } from "../packages/financial-engine/challenges";

interface SimulatorProps {
  currentBalance: number;
  safeToSpend: number;
  dailyBurn: number;
  daysRemaining: number;
}

export function TimeMachineSimulator({
  currentBalance,
  safeToSpend,
  dailyBurn,
  daysRemaining
}: SimulatorProps) {
  const [spendAmount, setSpendAmount] = useState(1500);
  const [activePreset, setActivePreset] = useState("Weekend Outing");
  const [challenges, setChallenges] = useState(exampleChallenges);

  const presets = [
    { label: "New Textbook / Course Material", amount: 1800 },
    { label: "Weekend Outing / Dinner", amount: 1500 },
    { label: "New Shoes / Fashion", amount: 3200 },
    { label: "Emergency Medical / Prescription", amount: 1200 },
    { label: "Month Wi-Fi / Data Bundle", amount: 1000 }
  ];

  const simulation = simulateSpendScenario(
    safeToSpend,
    spendAmount,
    [],
    []
  );

  const newSafeSpend = Math.max(0, safeToSpend - spendAmount);
  const newDaysRunway = dailyBurn > 0 ? Math.floor(newSafeSpend / dailyBurn) : daysRemaining;
  const daysLost = Math.max(0, daysRemaining - newDaysRunway);

  const toggleChallenge = (id: string) => {
    setChallenges(prev =>
      prev.map(c => c.id === id ? { ...c, isCompleted: !c.isCompleted } : c)
    );
  };

  return (
    <div style={{ display: "grid", gap: 24 }}>
      {/* Simulation Sandbox Card */}
      <div className="card-formal" style={{ background: "#0F172A", border: "1px solid #334155" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20, flexWrap: "wrap", gap: 10 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
              <Compass size={18} color="#38BDF8" />
              <h2 style={{ fontSize: 18, fontWeight: 700, color: "#F8FAFC", margin: 0 }}>
                Financial Time Machine
              </h2>
            </div>
            <p style={{ fontSize: 13, color: "#94A3B8" }}>
              Test discretionary purchases in a virtual sandbox before transferring funds.
            </p>
          </div>
          <span className="badge badge-blue">PREDICTIVE SIMULATION</span>
        </div>

        {/* Quick Presets */}
        <div style={{ marginBottom: 16 }}>
          <span style={{ fontSize: 11, color: "#64748B", display: "block", marginBottom: 6 }}>
            Quick scenario presets:
          </span>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {presets.map((p, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setSpendAmount(p.amount);
                  setActivePreset(p.label);
                }}
                className={activePreset === p.label ? "btn-primary btn-sm" : "btn-secondary btn-sm"}
                style={{ fontSize: 11, padding: "5px 10px" }}
              >
                {p.label} (KSh {p.amount.toLocaleString()})
              </button>
            ))}
          </div>
        </div>

        {/* Slider & Input */}
        <div style={{
          background: "#070D18",
          border: "1px solid #1E293B",
          borderRadius: 8,
          padding: 16,
          marginBottom: 20
        }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
            <span style={{ fontSize: 13, color: "#94A3B8" }}>Simulated Spend Amount:</span>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 14, color: "#64748B" }}>KSh</span>
              <input
                type="number"
                min="0"
                max={safeToSpend * 2}
                step="100"
                value={spendAmount}
                onChange={(e) => {
                  setSpendAmount(Number(e.target.value));
                  setActivePreset("Custom");
                }}
                style={{
                  width: 120,
                  fontSize: 16,
                  fontWeight: 700,
                  padding: "4px 8px",
                  textAlign: "right"
                }}
              />
            </div>
          </div>

          <input
            type="range"
            min="0"
            max={Math.max(10000, safeToSpend * 1.5)}
            step="100"
            value={spendAmount}
            onChange={(e) => {
              setSpendAmount(Number(e.target.value));
              setActivePreset("Custom");
            }}
            style={{ width: "100%", accentColor: "#38BDF8" }}
          />
        </div>

        {/* Projected Outcomes Grid */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 14 }}>
          {/* Box 1 */}
          <div style={{
            background: "#070D18",
            border: "1px solid #1E293B",
            borderRadius: 8,
            padding: 14
          }}>
            <span style={{ fontSize: 11, color: "#64748B", display: "block" }}>Current Safe Spend</span>
            <strong style={{ fontSize: 18, color: "#F8FAFC", display: "block", marginTop: 4 }}>
              KSh {safeToSpend.toLocaleString()}
            </strong>
            <span style={{ fontSize: 10, color: "#10B981" }}>Protected from rent</span>
          </div>

          {/* Box 2 */}
          <div style={{
            background: "#070D18",
            border: newSafeSpend < 1000 ? "1px solid #F43F5E" : "1px solid #1E293B",
            borderRadius: 8,
            padding: 14
          }}>
            <span style={{ fontSize: 11, color: "#64748B", display: "block" }}>Projected Safe Spend</span>
            <strong style={{
              fontSize: 18,
              color: newSafeSpend < 1000 ? "#F43F5E" : "#38BDF8",
              display: "block",
              marginTop: 4
            }}>
              KSh {newSafeSpend.toLocaleString()}
            </strong>
            <span style={{ fontSize: 10, color: "#94A3B8" }}>
              -{Math.round((spendAmount / Math.max(1, safeToSpend)) * 100)}% of allowance
            </span>
          </div>

          {/* Box 3 */}
          <div style={{
            background: "#070D18",
            border: daysLost > 3 ? "1px solid #F59E0B" : "1px solid #1E293B",
            borderRadius: 8,
            padding: 14
          }}>
            <span style={{ fontSize: 11, color: "#64748B", display: "block" }}>Projected Cash Runway</span>
            <strong style={{ fontSize: 18, color: daysLost > 3 ? "#F59E0B" : "#F8FAFC", display: "block", marginTop: 4 }}>
              {newDaysRunway} Days
            </strong>
            <span style={{ fontSize: 10, color: daysLost > 0 ? "#F43F5E" : "#10B981" }}>
              {daysLost > 0 ? `Loses ~${daysLost} days of safety` : "Zero runway penalty"}
            </span>
          </div>
        </div>

        {/* Verdict Advice */}
        <div style={{
          marginTop: 18,
          padding: 14,
          borderRadius: 8,
          background: spendAmount > safeToSpend ? "rgba(244, 63, 94, 0.12)" : spendAmount > safeToSpend * 0.3 ? "rgba(245, 158, 11, 0.1)" : "rgba(16, 185, 129, 0.1)",
          border: spendAmount > safeToSpend ? "1px solid #F43F5E" : spendAmount > safeToSpend * 0.3 ? "1px solid #F59E0B" : "1px solid #10B981",
          display: "flex",
          alignItems: "flex-start",
          gap: 12
        }}>
          {spendAmount > safeToSpend ? (
            <AlertTriangle size={20} color="#F43F5E" style={{ flexShrink: 0, marginTop: 2 }} />
          ) : spendAmount > safeToSpend * 0.3 ? (
            <AlertTriangle size={20} color="#F59E0B" style={{ flexShrink: 0, marginTop: 2 }} />
          ) : (
            <CheckCircle2 size={20} color="#10B981" style={{ flexShrink: 0, marginTop: 2 }} />
          )}

          <div>
            <h4 style={{
              fontSize: 13,
              fontWeight: 700,
              color: spendAmount > safeToSpend ? "#FDA4AF" : spendAmount > safeToSpend * 0.3 ? "#FCD34D" : "#A7F3D0"
            }}>
              {spendAmount > safeToSpend
                ? "High Hazard: Breaches Locked Reserve"
                : spendAmount > safeToSpend * 0.3
                ? "Caution: Significant Discretionary Drain"
                : "Safe Spend Approved"}
            </h4>
            <p style={{ fontSize: 12, color: "#CBD5E1", marginTop: 2 }}>
              {spendAmount > safeToSpend
                ? `Spending KSh ${spendAmount.toLocaleString()} will dip into your locked rent/exam reserve by KSh ${(spendAmount - safeToSpend).toLocaleString()}. We recommend postponing or finding a lower alternative.`
                : spendAmount > safeToSpend * 0.3
                ? `This purchase represents over 30% of your remaining free funds. Your daily burn will tighten for the next ${daysRemaining} days.`
                : `This transaction fits comfortably within your daily buffer and will not endanger your semester runway.`}
            </p>
          </div>
        </div>
      </div>

      {/* Student Financial Habits & Challenges */}
      <div className="card-formal" style={{ background: "#0F172A", border: "1px solid #334155" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <Award size={18} color="#F59E0B" />
            <h3 style={{ fontSize: 16, fontWeight: 700, color: "#F8FAFC" }}>
              Active Student Savings Challenges
            </h3>
          </div>
          <span className="badge badge-emerald">
            {challenges.filter(c => c.isCompleted).length} of {challenges.length} Done
          </span>
        </div>

        <div style={{ display: "grid", gap: 10 }}>
          {challenges.map((c) => (
            <div
              key={c.id}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "12px 14px",
                borderRadius: 8,
                background: "#070D18",
                border: c.isCompleted ? "1px solid #059669" : "1px solid #1E293B",
                gap: 12
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <button
                  onClick={() => toggleChallenge(c.id)}
                  style={{
                    width: 22,
                    height: 22,
                    borderRadius: 6,
                    border: c.isCompleted ? "none" : "1px solid #475569",
                    backgroundColor: c.isCompleted ? "#10B981" : "transparent",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    cursor: "pointer"
                  }}
                >
                  {c.isCompleted && <CheckCircle2 size={16} color="#FFFFFF" />}
                </button>
                <div>
                  <h4 style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: c.isCompleted ? "#94A3B8" : "#F8FAFC",
                    textDecoration: c.isCompleted ? "line-through" : "none"
                  }}>
                    {c.title}
                  </h4>
                  <p style={{ fontSize: 11, color: "#64748B" }}>
                    {c.description} · Target: {c.targetAmount ? `KSh ${c.targetAmount.toLocaleString()}` : "Discipline Habit"}
                  </p>
                </div>
              </div>

              <span className={c.difficulty === "EASY" ? "badge badge-blue" : "badge badge-amber"}>
                {c.difficulty}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
