"use client";

import React, { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  Wallet,
  ArrowDownLeft,
  ArrowUpRight,
  TrendingUp,
  ShieldCheck,
  AlertCircle,
  Plus,
  Search,
  Filter,
  CheckCircle2,
  Calendar,
  Layers,
  Sparkles,
  PieChart,
  Download,
  CreditCard,
  Lock,
  Compass,
  FileSpreadsheet
} from "lucide-react";

import { DashboardSidebar, DashboardTab } from "../../components/DashboardSidebar";
import { DashboardHeader } from "../../components/DashboardHeader";
import { AddTransactionModal } from "../../components/AddTransactionModal";
import { MpesaImportModal } from "../../components/MpesaImportModal";
import { TimeMachineSimulator } from "../../components/TimeMachineSimulator";

type Kind = "INCOME" | "EXPENSE" | "TRANSFER";

interface Account {
  id: string;
  name: string;
  type: string;
  provider?: string;
  balance: number;
  reserved: number;
}

interface TransactionEntry {
  id: string;
  kind: Kind;
  amount: number;
  category: string;
  note: string;
  date: string;
  accountId: string;
  reference?: string;
}

const STORAGE_KEY = "pesapilot_dashboard_data_v2";

const SEED_ACCOUNTS: Account[] = [
  { id: "acc-mpesa", name: "M-Pesa Safaricom", type: "MPESA", provider: "Safaricom", balance: 14500, reserved: 5000 },
  { id: "acc-bank", name: "Equity Student Account", type: "BANK", provider: "Equity Bank", balance: 32000, reserved: 0 },
  { id: "acc-savings", name: "Emergency Pocket", type: "SAVINGS", provider: "PesaPilot Lockbox", balance: 6500, reserved: 0 }
];

const SEED_TRANSACTIONS: TransactionEntry[] = [
  {
    id: "tx-1",
    kind: "INCOME",
    amount: 25000,
    category: "HELB & GRANTS",
    note: "HELB Upkeep disbursement",
    date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 5).toISOString().slice(0, 10),
    accountId: "acc-bank",
    reference: "HLB-99201-KE"
  },
  {
    id: "tx-2",
    kind: "EXPENSE",
    amount: 4500,
    category: "RENT & UTILITIES",
    note: "Off-campus Bedsitter Rent split",
    date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 3).toISOString().slice(0, 10),
    accountId: "acc-mpesa",
    reference: "QK894192M1"
  },
  {
    id: "tx-3",
    kind: "EXPENSE",
    amount: 650,
    category: "FOOD",
    note: "Campus Cafeteria Lunch",
    date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 2).toISOString().slice(0, 10),
    accountId: "acc-mpesa",
    reference: "QK910248P0"
  },
  {
    id: "tx-4",
    kind: "EXPENSE",
    amount: 250,
    category: "TRANSPORT",
    note: "Matatu Campus Express",
    date: new Date(Date.now() - 1000 * 60 * 60 * 12).toISOString().slice(0, 10),
    accountId: "acc-mpesa",
    reference: "QK940121L9"
  },
  {
    id: "tx-5",
    kind: "INCOME",
    amount: 3000,
    category: "SIDE HUSTLE",
    note: "Graphic design task payment",
    date: new Date(Date.now() - 1000 * 60 * 60 * 24 * 4).toISOString().slice(0, 10),
    accountId: "acc-mpesa",
    reference: "QK955102X4"
  }
];

export default function DashboardPage() {
  const router = useRouter();

  const [tab, setTab] = useState<DashboardTab>("overview");
  const [user, setUser] = useState<{ name: string; email: string } | null>({
    name: "Alex Kiprono",
    email: "alex@pesapilot.ke"
  });

  const [accounts, setAccounts] = useState<Account[]>(SEED_ACCOUNTS);
  const [entries, setEntries] = useState<TransactionEntry[]>(SEED_TRANSACTIONS);
  const [monthlyBudget, setMonthlyBudget] = useState(22000);
  const [savingsGoal, setSavingsGoal] = useState(10000);
  const [daysRemainingInSemester, setDaysRemainingInSemester] = useState(26);

  const [notice, setNotice] = useState<string>("");
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [isMpesaOpen, setIsMpesaOpen] = useState(false);
  const [txSearch, setTxSearch] = useState("");
  const [txCategoryFilter, setTxCategoryFilter] = useState("ALL");

  // Account creation state
  const [newAccName, setNewAccName] = useState("");
  const [newAccType, setNewAccType] = useState("MPESA");
  const [newAccBalance, setNewAccBalance] = useState("");
  const [newAccReserved, setNewAccReserved] = useState("");

  // Hydrate session & data from server or localStorage
  useEffect(() => {
    async function loadSession() {
      try {
        const res = await fetch("/api/me");
        if (res.ok) {
          const userData = await res.json();
          if (userData && userData.email) {
            setUser({ name: userData.name || "Student Pilot", email: userData.email });
          }
        }
      } catch {
        // Purely offline or client demo
      }

      // Load persistent local data if available
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed.accounts?.length) setAccounts(parsed.accounts);
          if (parsed.entries?.length) setEntries(parsed.entries);
          if (parsed.monthlyBudget) setMonthlyBudget(parsed.monthlyBudget);
          if (parsed.savingsGoal) setSavingsGoal(parsed.savingsGoal);
        }
      } catch {
        // Fall back to seed
      }
    }

    loadSession();
  }, []);

  // Persist locally
  useEffect(() => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ accounts, entries, monthlyBudget, savingsGoal })
      );
    } catch {
      // Storage unavailable
    }
  }, [accounts, entries, monthlyBudget, savingsGoal]);

  // Derived Financial Metrics
  const metrics = useMemo(() => {
    const totalBalance = accounts.reduce((sum, a) => sum + (Number(a.balance) || 0), 0);
    const totalReserved = accounts.reduce((sum, a) => sum + (Number(a.reserved) || 0), 0);
    const safeToSpend = Math.max(0, totalBalance - totalReserved);

    const totalExpense = entries
      .filter((e) => e.kind === "EXPENSE")
      .reduce((sum, e) => sum + e.amount, 0);

    const totalIncome = entries
      .filter((e) => e.kind === "INCOME")
      .reduce((sum, e) => sum + e.amount, 0);

    // Days with transactions
    const uniqueDates = new Set(entries.map((e) => e.date)).size;
    const dailyBurn = uniqueDates > 0 ? Math.round(totalExpense / Math.max(1, uniqueDates)) : 450;
    const runwayDays = dailyBurn > 0 ? Math.floor(safeToSpend / dailyBurn) : 90;

    // Categories aggregation
    const categoryTotals = entries
      .filter((e) => e.kind === "EXPENSE")
      .reduce<Record<string, number>>((acc, e) => {
        acc[e.category] = (acc[e.category] || 0) + e.amount;
        return acc;
      }, {});

    const sortedCategories = Object.entries(categoryTotals).sort((a, b) => b[1] - a[1]);

    const budgetRemaining = monthlyBudget - totalExpense;

    return {
      totalBalance,
      totalReserved,
      safeToSpend,
      totalExpense,
      totalIncome,
      dailyBurn,
      runwayDays,
      sortedCategories,
      budgetRemaining
    };
  }, [accounts, entries, monthlyBudget]);

  // Actions
  const handleAddTransaction = (newTx: {
    kind: Kind;
    amount: number;
    category: string;
    note: string;
    accountId: string;
    date: string;
  }) => {
    const entry: TransactionEntry = {
      id: `tx-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      ...newTx
    };

    // Update account balance
    setAccounts((prev) =>
      prev.map((acc) => {
        if (acc.id === newTx.accountId) {
          const delta = newTx.kind === "INCOME" ? newTx.amount : newTx.kind === "EXPENSE" ? -newTx.amount : 0;
          return { ...acc, balance: acc.balance + delta };
        }
        return acc;
      })
    );

    setEntries((prev) => [entry, ...prev]);
    setNotice(`Recorded ${newTx.kind.toLowerCase()}: KSh ${newTx.amount.toLocaleString()} in ${newTx.category}.`);
  };

  const handleImportMpesaSms = (parsedData: {
    kind: "EXPENSE" | "INCOME";
    amount: number;
    category: string;
    note: string;
    date: string;
    reference: string;
    balanceAfter: number;
  }) => {
    const mpesaAcc = accounts.find((a) => a.type === "MPESA") || accounts[0];
    const accountId = mpesaAcc?.id || "acc-mpesa";

    const entry: TransactionEntry = {
      id: `mpesa-${Date.now()}`,
      kind: parsedData.kind,
      amount: parsedData.amount,
      category: parsedData.category,
      note: parsedData.note,
      date: parsedData.date,
      accountId,
      reference: parsedData.reference
    };

    setAccounts((prev) =>
      prev.map((acc) => {
        if (acc.id === accountId) {
          // If balanceAfter is parsed from SMS, sync directly
          return {
            ...acc,
            balance: parsedData.balanceAfter > 0 ? parsedData.balanceAfter : (acc.balance + (parsedData.kind === "INCOME" ? parsedData.amount : -parsedData.amount))
          };
        }
        return acc;
      })
    );

    setEntries((prev) => [entry, ...prev]);
    setNotice(`M-Pesa SMS [${parsedData.reference}] extracted & account updated.`);
  };

  const handleCreateAccount = (e: React.FormEvent) => {
    e.preventDefault();
    const balance = Number(newAccBalance) || 0;
    const reserved = Number(newAccReserved) || 0;

    if (!newAccName.trim()) {
      setNotice("Please enter an account name.");
      return;
    }

    const newAcc: Account = {
      id: `acc-${Date.now()}`,
      name: newAccName.trim(),
      type: newAccType,
      provider: newAccType === "MPESA" ? "Safaricom" : newAccType === "BANK" ? "Bank Partner" : "Personal",
      balance,
      reserved
    };

    setAccounts((prev) => [...prev, newAcc]);
    setNewAccName("");
    setNewAccBalance("");
    setNewAccReserved("");
    setNotice(`Added account "${newAcc.name}".`);
  };

  const handleLogout = async () => {
    try {
      await fetch("/api/auth/logout", { method: "POST" });
    } catch {
      // offline
    }
    localStorage.removeItem("pesapilot_demo_session");
    router.push("/login");
  };

  const handleExportData = () => {
    const data = {
      user,
      accounts,
      entries,
      monthlyBudget,
      savingsGoal,
      exportedAt: new Date().toISOString()
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `pesapilot-cockpit-backup-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
    setNotice("Export downloaded securely.");
  };

  const filteredTransactions = useMemo(() => {
    return entries.filter((e) => {
      const matchSearch =
        e.note.toLowerCase().includes(txSearch.toLowerCase()) ||
        e.category.toLowerCase().includes(txSearch.toLowerCase()) ||
        (e.reference && e.reference.toLowerCase().includes(txSearch.toLowerCase()));
      const matchCat = txCategoryFilter === "ALL" || e.category === txCategoryFilter;
      return matchSearch && matchCat;
    });
  }, [entries, txSearch, txCategoryFilter]);

  return (
    <div style={{ display: "flex", minHeight: "100vh", backgroundColor: "var(--bg-primary)" }}>
      {/* Sidebar */}
      <DashboardSidebar
        currentTab={tab}
        onSelectTab={setTab}
        safeToSpend={metrics.safeToSpend}
        user={user}
        onLogout={handleLogout}
        onExport={handleExportData}
      />

      {/* Main Content Area */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
        {/* App Bar */}
        <DashboardHeader
          currentTab={tab}
          onOpenAddModal={() => setIsAddOpen(true)}
          onOpenMpesaModal={() => setIsMpesaOpen(true)}
          safeToSpend={metrics.safeToSpend}
        />

        {/* Notice Banner */}
        {notice && (
          <div style={{
            margin: "16px 28px 0 28px",
            padding: "10px 16px",
            background: "#064E3B",
            border: "1px solid #10B981",
            borderRadius: 8,
            color: "#A7F3D0",
            fontSize: 13,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <CheckCircle2 size={16} color="#34D399" />
              <span>{notice}</span>
            </div>
            <button onClick={() => setNotice("")} style={{ color: "#A7F3D0", padding: "2px 6px" }}>
              ✕
            </button>
          </div>
        )}

        {/* Tab View Container */}
        <main style={{ padding: "24px 28px 48px 28px", flex: 1 }}>
          {/* TAB 1: OVERVIEW COCKPIT */}
          {tab === "overview" && (
            <div className="view-enter" style={{ display: "grid", gap: 24 }}>
              {/* Primary KPI Grid */}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 16 }}>
                {/* Safe To Spend */}
                <div className="card-formal" style={{ background: "linear-gradient(135deg, #064E3B 0%, #0F172A 100%)", border: "1px solid #059669" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 11, fontWeight: 700, color: "#A7F3D0", letterSpacing: 0.5 }}>
                      SAFE TO SPEND
                    </span>
                    <span className="badge badge-emerald">Live</span>
                  </div>
                  <strong style={{ display: "block", fontSize: 28, fontWeight: 800, color: "#FFFFFF", margin: "10px 0 4px 0" }}>
                    KSh {metrics.safeToSpend.toLocaleString()}
                  </strong>
                  <span style={{ fontSize: 11, color: "#CBD5E1" }}>
                    After KSh {metrics.totalReserved.toLocaleString()} reserved for rent &amp; fees
                  </span>
                </div>

                {/* Total Balance */}
                <div className="card-formal">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 11, fontWeight: 600, color: "#94A3B8" }}>TOTAL COMBINED LIQUIDITY</span>
                    <Wallet size={16} color="#64748B" />
                  </div>
                  <strong style={{ display: "block", fontSize: 26, fontWeight: 700, color: "#F8FAFC", margin: "10px 0 4px 0" }}>
                    KSh {metrics.totalBalance.toLocaleString()}
                  </strong>
                  <span style={{ fontSize: 11, color: "#64748B" }}>
                    Across {accounts.length} connected accounts
                  </span>
                </div>

                {/* Daily Burn & Runway */}
                <div className="card-formal">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 11, fontWeight: 600, color: "#94A3B8" }}>SEMESTER RUNWAY</span>
                    <span className="badge badge-blue">{metrics.runwayDays} Days</span>
                  </div>
                  <strong style={{ display: "block", fontSize: 26, fontWeight: 700, color: "#38BDF8", margin: "10px 0 4px 0" }}>
                    ~KSh {metrics.dailyBurn.toLocaleString()}<span style={{ fontSize: 13, fontWeight: 400, color: "#94A3B8" }}>/day</span>
                  </strong>
                  <span style={{ fontSize: 11, color: "#64748B" }}>
                    Current spending velocity
                  </span>
                </div>

                {/* Monthly Outflow */}
                <div className="card-formal">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 11, fontWeight: 600, color: "#94A3B8" }}>MONTHLY EXPENDITURE</span>
                    <ArrowUpRight size={16} color="#F43F5E" />
                  </div>
                  <strong style={{ display: "block", fontSize: 26, fontWeight: 700, color: "#FDA4AF", margin: "10px 0 4px 0" }}>
                    KSh {metrics.totalExpense.toLocaleString()}
                  </strong>
                  <span style={{ fontSize: 11, color: "#64748B" }}>
                    Income: +KSh {metrics.totalIncome.toLocaleString()}
                  </span>
                </div>
              </div>

              {/* Middle Section: Cash Flow & Survival Gauge */}
              <div style={{ display: "grid", gridTemplateColumns: "1.4fr 1fr", gap: 20 }}>
                {/* Category Outflow Progress */}
                <div className="card-formal">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                    <h3 style={{ fontSize: 15, fontWeight: 700, color: "#F8FAFC" }}>Spending Breakdown by Category</h3>
                    <button onClick={() => setTab("budget")} className="btn-ghost btn-sm" style={{ fontSize: 12 }}>
                      View Budgets →
                    </button>
                  </div>

                  {metrics.sortedCategories.length ? (
                    <div style={{ display: "grid", gap: 14 }}>
                      {metrics.sortedCategories.map(([category, amount]) => {
                        const pct = Math.min(100, Math.round((amount / Math.max(metrics.totalExpense, 1)) * 100));
                        return (
                          <div key={category}>
                            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 4 }}>
                              <span style={{ color: "#CBD5E1", fontWeight: 600 }}>{category}</span>
                              <span style={{ color: "#F8FAFC" }}>
                                KSh {amount.toLocaleString()} <span style={{ color: "#64748B" }}>({pct}%)</span>
                              </span>
                            </div>
                            <div style={{ height: 6, backgroundColor: "#070D18", borderRadius: 3, overflow: "hidden" }}>
                              <div style={{
                                width: `${pct}%`,
                                height: "100%",
                                backgroundColor: category.includes("RENT") ? "#F59E0B" : category.includes("FOOD") ? "#10B981" : "#38BDF8",
                                borderRadius: 3
                              }} />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <p style={{ color: "#64748B", fontSize: 13, padding: "20px 0", textAlign: "center" }}>
                      No expenses logged yet. Add your first transaction or import an SMS.
                    </p>
                  )}
                </div>

                {/* Wallets & Accounts Quick Card */}
                <div className="card-formal">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                    <h3 style={{ fontSize: 15, fontWeight: 700, color: "#F8FAFC" }}>Wallets &amp; Accounts</h3>
                    <button onClick={() => setTab("accounts")} className="btn-ghost btn-sm" style={{ fontSize: 12 }}>
                      Manage →
                    </button>
                  </div>

                  <div style={{ display: "grid", gap: 10 }}>
                    {accounts.map((acc) => (
                      <div
                        key={acc.id}
                        style={{
                          display: "flex",
                          justifyContent: "space-between",
                          alignItems: "center",
                          padding: "10px 12px",
                          borderRadius: 8,
                          backgroundColor: "#070D18",
                          border: "1px solid #1E293B"
                        }}
                      >
                        <div>
                          <strong style={{ fontSize: 13, color: "#F8FAFC", display: "block" }}>{acc.name}</strong>
                          <span style={{ fontSize: 11, color: "#64748B" }}>
                            {acc.type} {acc.reserved > 0 ? `· KSh ${acc.reserved.toLocaleString()} locked` : ""}
                          </span>
                        </div>
                        <span style={{ fontSize: 14, fontWeight: 700, color: "#10B981" }}>
                          KSh {acc.balance.toLocaleString()}
                        </span>
                      </div>
                    ))}
                  </div>

                  <div style={{ marginTop: 16, paddingTop: 14, borderTop: "1px solid #1E293B" }}>
                    <button
                      onClick={() => setIsMpesaOpen(true)}
                      className="btn-secondary btn-sm"
                      style={{ width: "100%", justifyContent: "center" }}
                    >
                      <Plus size={14} />
                      <span>Parse M-Pesa Receipt</span>
                    </button>
                  </div>
                </div>
              </div>

              {/* Recent Ledger Feed */}
              <div className="card-formal">
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                  <h3 style={{ fontSize: 15, fontWeight: 700, color: "#F8FAFC" }}>Recent Activity Ledger</h3>
                  <button onClick={() => setTab("transactions")} className="btn-ghost btn-sm" style={{ fontSize: 12 }}>
                    Open Full Ledger ({entries.length}) →
                  </button>
                </div>

                <div style={{ display: "grid", gap: 8 }}>
                  {entries.slice(0, 5).map((entry) => (
                    <div
                      key={entry.id}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        padding: "10px 12px",
                        borderRadius: 6,
                        backgroundColor: "#070D18",
                        border: "1px solid #1E293B"
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                        <div style={{
                          width: 32,
                          height: 32,
                          borderRadius: "50%",
                          backgroundColor: entry.kind === "INCOME" ? "rgba(16, 185, 129, 0.15)" : "rgba(244, 63, 94, 0.15)",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center"
                        }}>
                          {entry.kind === "INCOME" ? (
                            <ArrowDownLeft size={16} color="#10B981" />
                          ) : (
                            <ArrowUpRight size={16} color="#F43F5E" />
                          )}
                        </div>
                        <div>
                          <strong style={{ fontSize: 13, color: "#F8FAFC", display: "block" }}>
                            {entry.note || entry.category}
                          </strong>
                          <span style={{ fontSize: 11, color: "#64748B" }}>
                            {entry.category} · {entry.date} {entry.reference ? `· ${entry.reference}` : ""}
                          </span>
                        </div>
                      </div>

                      <strong style={{
                        fontSize: 14,
                        color: entry.kind === "INCOME" ? "#10B981" : "#F8FAFC"
                      }}>
                        {entry.kind === "INCOME" ? "+" : "-"}KSh {entry.amount.toLocaleString()}
                      </strong>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* TAB 2: TRANSACTIONS & SMS */}
          {tab === "transactions" && (
            <div className="view-enter" style={{ display: "grid", gap: 20 }}>
              {/* Filter & Action Bar */}
              <div style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
                gap: 12,
                backgroundColor: "#0F172A",
                padding: "14px 18px",
                borderRadius: 10,
                border: "1px solid #1E293B"
              }}>
                <div style={{ display: "flex", gap: 10, alignItems: "center", flex: 1, minWidth: 260 }}>
                  <div style={{ position: "relative", flex: 1 }}>
                    <Search size={15} color="#64748B" style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)" }} />
                    <input
                      type="text"
                      placeholder="Search transactions, paybills, references..."
                      value={txSearch}
                      onChange={(e) => setTxSearch(e.target.value)}
                      style={{ paddingLeft: 34, fontSize: 13 }}
                    />
                  </div>

                  <select
                    value={txCategoryFilter}
                    onChange={(e) => setTxCategoryFilter(e.target.value)}
                    style={{ width: "auto", fontSize: 13 }}
                  >
                    <option value="ALL">All Categories</option>
                    <option value="FOOD">Food</option>
                    <option value="TRANSPORT">Transport</option>
                    <option value="RENT & UTILITIES">Rent &amp; Utilities</option>
                    <option value="HELB & GRANTS">HELB &amp; Grants</option>
                    <option value="SIDE HUSTLE">Side Hustle</option>
                  </select>
                </div>

                <div style={{ display: "flex", gap: 10 }}>
                  <button onClick={() => setIsMpesaOpen(true)} className="btn-secondary btn-sm" style={{ borderColor: "#059669", color: "#34D399" }}>
                    <span>Paste M-Pesa SMS</span>
                  </button>
                  <button onClick={() => setIsAddOpen(true)} className="btn-primary btn-sm">
                    <Plus size={15} />
                    <span>Record Manual Entry</span>
                  </button>
                </div>
              </div>

              {/* Transactions Ledger Table */}
              <div className="card-formal" style={{ padding: 0, overflow: "hidden" }}>
                <div style={{
                  display: "grid",
                  gridTemplateColumns: "100px 1.5fr 1fr 1fr 140px",
                  padding: "12px 18px",
                  backgroundColor: "#070D18",
                  borderBottom: "1px solid #1E293B",
                  fontSize: 12,
                  fontWeight: 600,
                  color: "#94A3B8"
                }}>
                  <span>DATE</span>
                  <span>DESCRIPTION / NOTE</span>
                  <span>CATEGORY</span>
                  <span>SOURCE ACCOUNT</span>
                  <span style={{ textAlign: "right" }}>AMOUNT</span>
                </div>

                <div style={{ maxHeight: "65vh", overflowY: "auto" }}>
                  {filteredTransactions.length ? (
                    filteredTransactions.map((tx) => {
                      const acc = accounts.find((a) => a.id === tx.accountId);
                      return (
                        <div
                          key={tx.id}
                          style={{
                            display: "grid",
                            gridTemplateColumns: "100px 1.5fr 1fr 1fr 140px",
                            padding: "14px 18px",
                            borderBottom: "1px solid #1E293B",
                            fontSize: 13,
                            alignItems: "center"
                          }}
                        >
                          <span style={{ color: "#64748B", fontSize: 12 }}>{tx.date}</span>
                          <div>
                            <strong style={{ color: "#F8FAFC", display: "block" }}>{tx.note}</strong>
                            {tx.reference && (
                              <span style={{ fontSize: 10, color: "#38BDF8", fontFamily: "monospace" }}>
                                Ref: {tx.reference}
                              </span>
                            )}
                          </div>
                          <div>
                            <span className="badge badge-neutral" style={{ fontSize: 11 }}>
                              {tx.category}
                            </span>
                          </div>
                          <span style={{ color: "#94A3B8", fontSize: 12 }}>{acc?.name || "M-Pesa"}</span>
                          <strong style={{
                            textAlign: "right",
                            color: tx.kind === "INCOME" ? "#10B981" : "#F8FAFC",
                            fontSize: 14
                          }}>
                            {tx.kind === "INCOME" ? "+" : "-"}KSh {tx.amount.toLocaleString()}
                          </strong>
                        </div>
                      );
                    })
                  ) : (
                    <div style={{ padding: "40px 0", textAlign: "center", color: "#64748B" }}>
                      <p>No transactions match your current search criteria.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: WALLETS & ACCOUNTS */}
          {tab === "accounts" && (
            <div className="view-enter" style={{ display: "grid", gap: 24 }}>
              {/* Account Cards Grid */}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 18 }}>
                {accounts.map((acc) => (
                  <div key={acc.id} className="card-formal" style={{ background: "#0F172A", border: "1px solid #334155" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                      <div>
                        <span className="badge badge-neutral" style={{ fontSize: 10, marginBottom: 6 }}>
                          {acc.type}
                        </span>
                        <h3 style={{ fontSize: 16, fontWeight: 700, color: "#F8FAFC" }}>{acc.name}</h3>
                      </div>
                      <CreditCard size={18} color="#10B981" />
                    </div>

                    <div style={{ margin: "16px 0" }}>
                      <span style={{ fontSize: 11, color: "#64748B", display: "block" }}>Current Balance</span>
                      <strong style={{ fontSize: 26, fontWeight: 800, color: "#10B981" }}>
                        KSh {acc.balance.toLocaleString()}
                      </strong>
                    </div>

                    <div style={{
                      background: "#070D18",
                      borderRadius: 6,
                      padding: "8px 12px",
                      display: "flex",
                      justifyContent: "space-between",
                      fontSize: 12,
                      color: "#94A3B8"
                    }}>
                      <span>Locked / Reserved:</span>
                      <strong style={{ color: "#F59E0B" }}>KSh {acc.reserved.toLocaleString()}</strong>
                    </div>
                  </div>
                ))}
              </div>

              {/* Add New Account Form */}
              <div className="card-formal" style={{ maxWidth: 540 }}>
                <h3 style={{ fontSize: 16, fontWeight: 700, color: "#F8FAFC", marginBottom: 14 }}>
                  Connect Another Account or Pocket
                </h3>

                <form onSubmit={handleCreateAccount} style={{ display: "grid", gap: 12 }}>
                  <div>
                    <label style={{ display: "block", fontSize: 12, color: "#94A3B8", marginBottom: 4 }}>
                      Account Name
                    </label>
                    <input
                      type="text"
                      placeholder="e.g. Co-op Student Account or Cash Stash"
                      value={newAccName}
                      onChange={(e) => setNewAccName(e.target.value)}
                    />
                  </div>

                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                    <div>
                      <label style={{ display: "block", fontSize: 12, color: "#94A3B8", marginBottom: 4 }}>
                        Account Type
                      </label>
                      <select
                        value={newAccType}
                        onChange={(e) => setNewAccType(e.target.value)}
                      >
                        <option value="MPESA">M-Pesa</option>
                        <option value="BANK">Bank</option>
                        <option value="SAVINGS">Savings Lockbox</option>
                        <option value="CASH">Cash Reserve</option>
                      </select>
                    </div>

                    <div>
                      <label style={{ display: "block", fontSize: 12, color: "#94A3B8", marginBottom: 4 }}>
                        Opening Balance (KSh)
                      </label>
                      <input
                        type="number"
                        placeholder="0"
                        value={newAccBalance}
                        onChange={(e) => setNewAccBalance(e.target.value)}
                      />
                    </div>
                  </div>

                  <div>
                    <label style={{ display: "block", fontSize: 12, color: "#94A3B8", marginBottom: 4 }}>
                      Reserved Balance (Locked for rent/fees)
                    </label>
                    <input
                      type="number"
                      placeholder="0"
                      value={newAccReserved}
                      onChange={(e) => setNewAccReserved(e.target.value)}
                    />
                  </div>

                  <button type="submit" className="btn-primary" style={{ marginTop: 6 }}>
                    <Plus size={16} />
                    <span>Add Account</span>
                  </button>
                </form>
              </div>
            </div>
          )}

          {/* TAB 4: BUDGET & CATEGORIES */}
          {tab === "budget" && (
            <div className="view-enter" style={{ display: "grid", gap: 24 }}>
              {/* Budget Overview Hero */}
              <div className="card-formal" style={{ background: "linear-gradient(135deg, #0B132B 0%, #1E293B 100%)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
                  <div>
                    <span className="badge badge-emerald" style={{ marginBottom: 6 }}>MONTHLY PACING</span>
                    <h2 style={{ fontSize: 24, fontWeight: 800, color: "#F8FAFC" }}>
                      KSh {metrics.budgetRemaining.toLocaleString()} Remaining
                    </h2>
                    <p style={{ color: "#94A3B8", fontSize: 13, marginTop: 4 }}>
                      Monthly budget cap: KSh {monthlyBudget.toLocaleString()} · Spent: KSh {metrics.totalExpense.toLocaleString()}
                    </p>
                  </div>

                  <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                    <span style={{ fontSize: 12, color: "#94A3B8" }}>Edit Budget Cap:</span>
                    <input
                      type="number"
                      value={monthlyBudget}
                      onChange={(e) => setMonthlyBudget(Number(e.target.value) || 0)}
                      style={{ width: 120, fontSize: 14, fontWeight: 700 }}
                    />
                  </div>
                </div>

                {/* Main Progress Bar */}
                <div style={{ height: 10, backgroundColor: "#070D18", borderRadius: 5, overflow: "hidden", margin: "20px 0 10px 0" }}>
                  <div style={{
                    width: `${Math.min(100, Math.round((metrics.totalExpense / Math.max(monthlyBudget, 1)) * 100))}%`,
                    height: "100%",
                    backgroundColor: metrics.budgetRemaining < 0 ? "#F43F5E" : "#10B981",
                    borderRadius: 5
                  }} />
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#64748B" }}>
                  <span>0% spent</span>
                  <span>{Math.round((metrics.totalExpense / Math.max(monthlyBudget, 1)) * 100)}% utilized</span>
                  <span>100% cap</span>
                </div>
              </div>

              {/* Savings Goal Section */}
              <div className="card-formal">
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
                  <div>
                    <h3 style={{ fontSize: 16, fontWeight: 700, color: "#F8FAFC" }}>Emergency Buffer Milestone</h3>
                    <p style={{ fontSize: 12, color: "#94A3B8" }}>Protecting yourself against sudden repairs or unexpected costs</p>
                  </div>
                  <strong style={{ fontSize: 18, color: "#10B981" }}>
                    KSh {accounts.find(a => a.type === "SAVINGS")?.balance.toLocaleString() || 6500} of KSh {savingsGoal.toLocaleString()}
                  </strong>
                </div>

                <div style={{ height: 8, backgroundColor: "#070D18", borderRadius: 4, overflow: "hidden", marginBottom: 14 }}>
                  <div style={{
                    width: `${Math.min(100, Math.round(((accounts.find(a => a.type === "SAVINGS")?.balance || 6500) / Math.max(savingsGoal, 1)) * 100))}%`,
                    height: "100%",
                    backgroundColor: "#10B981",
                    borderRadius: 4
                  }} />
                </div>

                <button
                  onClick={() => {
                    setAccounts(prev =>
                      prev.map(a => a.type === "SAVINGS" ? { ...a, balance: a.balance + 500 } : a)
                    );
                    setNotice("Added KSh 500 to emergency pocket.");
                  }}
                  className="btn-secondary btn-sm"
                >
                  <Plus size={14} />
                  <span>Transfer KSh 500 to Emergency Pocket</span>
                </button>
              </div>
            </div>
          )}

          {/* TAB 5: WHAT-IF SIMULATOR */}
          {tab === "simulator" && (
            <div className="view-enter">
              <TimeMachineSimulator
                currentBalance={metrics.totalBalance}
                safeToSpend={metrics.safeToSpend}
                dailyBurn={metrics.dailyBurn}
                daysRemaining={daysRemainingInSemester}
              />
            </div>
          )}
        </main>
      </div>

      {/* Modals */}
      <AddTransactionModal
        isOpen={isAddOpen}
        onClose={() => setIsAddOpen(false)}
        accounts={accounts}
        onAdd={handleAddTransaction}
      />

      <MpesaImportModal
        isOpen={isMpesaOpen}
        onClose={() => setIsMpesaOpen(false)}
        onImport={handleImportMpesaSms}
        existingReferences={entries.map(e => e.reference || "").filter(Boolean)}
      />
    </div>
  );
}
